#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    int oddX = 0, oddY = 0;
    bool canSwap = false;

    for (int i = 0; i < n; ++i) {
        int x, y;
        cin >> x >> y;

        oddX += x % 2;
        oddY += y % 2;

        if ((x % 2) != (y % 2))
            canSwap = true;
    }

    if (oddX % 2 == 0 && oddY % 2 == 0)
        cout << 0 << '\n';
    else if (oddX % 2 != 0 && oddY % 2 != 0 && canSwap)
        cout << 1 << '\n';
    else
        cout << -1 << '\n';

    return 0;
}

